public string? GetCurrentControllerName()
{
    // The view model resolves the selected/saved profile name before its
    // type fallback. Its fallback calls the static helper, not this method.
    var controllerName = taskQueueViewModel.GetCurrentControllerName();
    var selected = maaInterface?.Controller?.FirstOrDefault(controller =>
        controller.ControllerType == taskQueueViewModel.CurrentController
        && !string.IsNullOrWhiteSpace(controllerName)
        && controller.Name?.Equals(controllerName, StringComparison.OrdinalIgnoreCase) == true);
    return selected?.Name ?? GetControllerName(taskQueueViewModel.CurrentController, maaInterface);
}
